INSERT INTO public.content_collections (key, data, updated_at) VALUES ('faq', '[{"q":{"en":"Is submitting an inquiry a booking?","ar":"هل يٌعد إرسال الاستفسار حجزًا؟","ro":"Trimiterea unei solicitări înseamnă rezervare?"},"a":{"en":"No. An inquiry is non-binding. We review your ideas and prepare a personalised proposed itinerary and quotation. Nothing is booked until you accept a written offer from an authorised travel team.","ar":"لا. الاستفسار غير مٌلزِم. نراجع أفكارك ونعدّ برنامجًا مقترحًا وعرض سعر مخصصًا. لا يتم حجز أي شيء قبل قبولك لعرض مكتوب من فريق سفر مٌخوَّل.","ro":"Nu. Solicitarea nu este obligatorie. Analizăm ideile tale și pregătim un itinerariu propus și o ofertă personalizată. Nimic nu se rezervă până nu accepți o ofertă scrisă de la o echipă de turism autorizată."}},{"q":{"en":"Can we travel privately or as a group?","ar":"هل يمكننا السفر بشكل خاص أو ضمن مجموعة؟","ro":"Putem călători privat sau în grup?"},"a":{"en":"Both can be requested: private journeys for families or couples, and small custom groups — including groups of around 10–12 travellers. Arrangements are subject to supplier confirmation.","ar":"يمكن طلب الخيارين: رحلات خاصة للعائلات أو الأزواج، ومجموعات صغيرة مخصصة بما فيها مجموعات من نحو 10–12 مسافرًا، مع خضوع الترتيبات لتأكيد المزودين.","ro":"Ambele pot fi solicitate: călătorii private pentru familii sau cupluri și grupuri mici personalizate — inclusiv de aproximativ 10–12 persoane. Aranjamentele depind de confirmarea furnizorilor."}},{"q":{"en":"Can the itinerary be customised?","ar":"هل يمكن تخصيص البرنامج؟","ro":"Itinerariul poate fi personalizat?"},"a":{"en":"Yes. Every journey shown is an illustrative concept. Duration, pacing, regions and interests can all be adjusted in your proposal.","ar":"نعم. كل رحلة معروضة هي تصوّر توضيحي، ويمكن تعديل المدة والإيقاع والمناطق والاهتمامات في المقترح الخاص بك.","ro":"Da. Fiecare circuit prezentat este un concept ilustrativ. Durata, ritmul, regiunile și interesele pot fi ajustate în propunerea ta."}},{"q":{"en":"Can you accommodate family needs and dietary requests?","ar":"هل يمكنكم مراعاة احتياجات العائلة والطلبات الغذائية؟","ro":"Puteți ține cont de nevoile familiei și de cerințele alimentare?"},"a":{"en":"You can share family needs and dietary preferences, including halal requests, in your inquiry. We will look for suitable options, but nothing is promised until confirmed in writing.","ar":"يمكنك مشاركة احتياجات العائلة والتفضيلات الغذائية، بما في ذلك طلبات الطعام الحلال، في استفسارك. سنبحث عن خيارات مناسبة، لكن لا يٌلتزم بأي شيء قبل تأكيده كتابيًا.","ro":"Poți menționa nevoile familiei și preferințele alimentare, inclusiv cereri halal, în solicitare. Vom căuta opțiuni potrivite, dar nimic nu este promis până la confirmarea scrisă."}},{"q":{"en":"What accommodation standard can we expect?","ar":"ما مستوى الإقامة الذي يمكن توقعه؟","ro":"Ce standard de cazare putem aștepta?"},"a":{"en":"You choose a preferred comfort level. Specific hotels or guesthouses are proposed only in a confirmed quotation.","ar":"تختار مستوى الراحة المفضل لديك، وتٌقترح الفنادق أو بيوت الضيافة المحددة فقط في عرض سعر مؤكد.","ro":"Tu alegi nivelul de confort dorit. Hotelurile sau pensiunile concrete se propun doar într-o ofertă confirmată."}}]'::jsonb, now()) ON CONFLICT (key) DO NOTHING;